import { FormEvent, useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Routes, useNavigate } from 'react-router-dom';
import { api, Category, Listing } from './api';
import ThemeToggle from './components/ThemeToggle';

type User = { id: string; full_name: string; email: string; campus?: string; role: 'customer' | 'seller' | 'admin'; kyc_status?: string };
type Notice = { kind: 'success' | 'error' | 'info'; text: string };
const errorText = (error: any, fallback: string) => error?.response?.data?.error || fallback;
const money = (amount: string | number, currency = 'SZL') => `${currency === 'SZL' ? 'E' : `${currency} `}${Number(amount).toLocaleString()}`;

function Brand() { return <Link to="/" className="brand" aria-label="StudentXchange home"><img className="brand-logo" src="/studentxchange-logo.png" alt="" /><span>Student<span className="brand-blue">Xchange</span></span></Link>; }

function ListingGallery({ images, title, category, type, variant }: { images?: string[]; title: string; category: string; type: string; variant: number }) {
  const [active, setActive] = useState(0);
  const photos = images || [];
  const current = Math.min(active, Math.max(photos.length - 1, 0));
  return <>
    <div className={`listing-visual visual-${variant}`}>
      {photos[current] && <img className="listing-photo" src={photos[current]} alt={`${title}, photo ${current + 1} of ${photos.length}`} loading="lazy" onError={(event) => event.currentTarget.remove()} />}
      <span className="listing-category">{category}</span><span className="visual-glyph">{type === 'service' ? 'S' : 'P'}</span>
      {photos.length > 1 && <><button type="button" className="gallery-arrow gallery-previous" aria-label={`Previous photo of ${title}`} onClick={() => setActive((current - 1 + photos.length) % photos.length)}>‹</button><button type="button" className="gallery-arrow gallery-next" aria-label={`Next photo of ${title}`} onClick={() => setActive((current + 1) % photos.length)}>›</button><span className="gallery-count" aria-live="polite">{current + 1}/{photos.length}</span></>}
    </div>
    {photos.length > 1 && <div className="listing-thumbnails" aria-label={`${title} photos`}>{photos.map((photo, index) => <button type="button" className={`listing-thumbnail${index === current ? ' active' : ''}`} key={`${index}-${photo.slice(0, 32)}`} aria-label={`View photo ${index + 1} of ${title}`} aria-pressed={index === current} onClick={() => setActive(index)}><img src={photo} alt="" loading="lazy" /></button>)}</div>}
  </>;
}

function App() {
  const navigate = useNavigate();
  const [kind, setKind] = useState<'physical' | 'service'>('physical');
  const [listingFilter, setListingFilter] = useState<'all' | 'physical' | 'service'>('all');
  const [search, setSearch] = useState('');
  const [dialog, setDialog] = useState<'login' | 'register' | 'sell' | null>(null);
  const [notice, setNotice] = useState<Notice | null>(null);
  const [authEmail, setAuthEmail] = useState('');
  const [listingImageData, setListingImageData] = useState<string[]>([]);
  const [sellerActivating, setSellerActivating] = useState(false);
  const [sellerActivationError, setSellerActivationError] = useState('');
  const [user, setUser] = useState<User | null>(() => { try { return JSON.parse(localStorage.getItem('sx-user') || 'null'); } catch { return null; } });
  const qc = useQueryClient();
  const currentUser = useQuery({ queryKey: ['current-user'], queryFn: async () => (await api.get<User>('/auth/me')).data, enabled: !!localStorage.getItem('sx-token'), retry: false, refetchInterval: user?.role === 'admin' ? false : 15000, refetchOnWindowFocus: true });
  useEffect(() => { if (currentUser.data) { localStorage.setItem('sx-user', JSON.stringify(currentUser.data)); setUser(currentUser.data); } }, [currentUser.data]);
  const categories = useQuery({ queryKey: ['categories'], queryFn: async () => (await api.get<Category[]>('/categories')).data, retry: 1 });
  const listingsQuery = useQuery({ queryKey: ['listings', listingFilter, search], queryFn: async () => (await api.get<Listing[]>('/listings', { params: { type: listingFilter === 'all' ? undefined : listingFilter, search } })).data, retry: 1 });
  const featuredListingQuery = useQuery({ queryKey: ['featured-listing'], queryFn: async () => { const items = (await api.get<Listing[]>('/listings')).data; return items.find((item) => item.images?.[0]) || items[0] || null; }, retry: 1 });
  const featuredListing = featuredListingQuery.data;
  const cats = (categories.data || []).filter((c) => listingFilter === 'all' || c.category_type === listingFilter);
  const allListings = listingsQuery.data || [];
  const listings = allListings;
  const authMutation = useMutation({
    mutationFn: async (payload: Record<string, string>) => (await api.post(dialog === 'register' ? '/auth/register' : '/auth/login', payload)).data,
    onSuccess: (data) => {
      if (data.token) localStorage.setItem('sx-token', data.token);
      localStorage.setItem('sx-user', JSON.stringify(data.user)); setUser(data.user); qc.setQueryData(['current-user'], data.user); setDialog(null);
      if (data.user.role === 'admin') navigate('/admin'); else if (data.user.role === 'seller') navigate('/seller');
      setNotice({ kind: 'success', text: 'You are signed in.' });
    },
    onError: (error:any) => { if(error?.response?.data?.email)setAuthEmail(error.response.data.email); }
  });
  const resendVerificationMutation=useMutation({mutationFn:async(email:string)=>(await api.post('/auth/resend-verification',{email})).data});
  const listingMutation = useMutation({ mutationFn: async (payload: Record<string, string | string[]>) => (await api.post('/listings', payload)).data,
    onSuccess: () => { setDialog(null); setListingImageData([]); setNotice({ kind: 'success', text: 'Listing submitted for admin review.' }); qc.invalidateQueries({ queryKey: ['listings'] }); qc.invalidateQueries({ queryKey: ['featured-listing'] }); qc.invalidateQueries({ queryKey: ['seller'] }); qc.invalidateQueries({ queryKey: ['admin','listings'] }); },
    onError: (error) => setNotice({ kind: 'error', text: errorText(error, 'Could not publish the listing.') }) });

  function submitAuth(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget).entries()); authMutation.mutate(Object.fromEntries(Object.entries(data).map(([k,v]) => [k, String(v)]))); }
  function submitListing(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget).entries()); listingMutation.mutate({ ...Object.fromEntries(Object.entries(data).map(([k,v]) => [k, String(v)])), listing_type: kind, image_urls: listingImageData }); }
  function compressListingImage(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      if (!['image/jpeg','image/png','image/webp'].includes(file.type)) { reject(new Error('Choose JPG, PNG or WebP images.')); return; }
      if (file.size > 700 * 1024) { reject(new Error('Each image must be 700 KB or smaller.')); return; }
      const reader = new FileReader(); reader.onerror = () => reject(new Error('Could not read an image file.')); reader.onload = () => {
        const image = new Image(); image.onerror = () => reject(new Error('Could not load an image file.')); image.onload = () => {
          const scale = Math.min(1, 720 / Math.max(image.width, image.height)); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round(image.width * scale)); canvas.height = Math.max(1, Math.round(image.height * scale));
          const context = canvas.getContext('2d'); if (!context) { reject(new Error('Image compression is unavailable in this browser.')); return; }
          context.drawImage(image, 0, 0, canvas.width, canvas.height);
          for (const quality of [0.78,0.68,0.58,0.48,0.38,0.28]) { const compressed = canvas.toDataURL('image/jpeg', quality); if (compressed.length <= 72000) { resolve(compressed); return; } }
          reject(new Error('An image could not be compressed small enough. Try a simpler or smaller image.'));
        }; image.src = String(reader.result || '');
      }; reader.readAsDataURL(file);
    });
  }
  async function loadListingImages(files?: FileList | null) {
    const selected = Array.from(files || []); if (!selected.length) { setListingImageData([]); return; }
    if (selected.length > 5) { setListingImageData([]); setNotice({kind:'error',text:'Choose up to 5 images for one listing.'}); return; }
    try { setListingImageData(await Promise.all(selected.map(compressListingImage))); }
    catch (error) { setListingImageData([]); setNotice({kind:'error',text:error instanceof Error ? error.message : 'Could not process these images.'}); }
  }
  function signOut() { localStorage.removeItem('sx-token'); localStorage.removeItem('sx-user'); qc.removeQueries({ queryKey: ['current-user'] }); setUser(null); setNotice({ kind: 'success', text: 'You are signed out.' }); navigate('/'); }
  async function becomeSeller() {
    if (sellerActivating) return;
    setSellerActivating(true);
    setSellerActivationError('');
    try {
      const response = await api.post('/seller/activate');
      localStorage.setItem('sx-token', response.data.token);
      localStorage.setItem('sx-user', JSON.stringify(response.data.user));
      setUser(response.data.user); qc.setQueryData(['current-user'], response.data.user);
      navigate('/seller');
      setNotice({ kind: 'success', text: 'Seller studio is ready. Submit student verification to publish listings.' });
    } catch (error) {
      setSellerActivationError(errorText(error, 'Could not activate seller access. Please try again.'));
    } finally {
      setSellerActivating(false);
    }
  }
  async function requestListing(listing: Listing) {
    if (!user) { setDialog('login'); setNotice({ kind: 'info', text: 'Sign in to request an item or service.' }); return; }
    try { await api.post('/orders', { listing_id: listing.id }); await qc.invalidateQueries({ queryKey: ['orders'] }); navigate('/orders'); setNotice({ kind: 'success', text: 'Order created. Review it in My orders to continue.' }); }
    catch (error) { setNotice({ kind: 'error', text: errorText(error, 'Could not create the order.') }); }
  }

  const activeUser = currentUser.data || user;
  if ((user || localStorage.getItem('sx-token')) && !user && currentUser.isLoading) return <KycChecking onSignOut={signOut}/>;
  if (user && user.role !== 'admin' && !user.kyc_status && currentUser.isLoading) return <KycChecking onSignOut={signOut}/>;
  if (activeUser && activeUser.role !== 'admin' && activeUser.kyc_status !== 'approved') return <KycGate user={activeUser} onSignOut={signOut} onRefresh={() => currentUser.refetch()} onSubmitted={() => { const pending={...activeUser,kyc_status:'pending'};setUser(pending);localStorage.setItem('sx-user',JSON.stringify(pending));qc.setQueryData(['current-user'],pending); }} />;

  return <>
    <Routes>
      <Route path="/verify-email" element={<VerifyEmailPage/>} />
      <Route path="/admin" element={<AdminPage user={user} onLogin={() => setDialog('login')} onSignOut={signOut} />} />
      <Route path="/orders" element={<OrdersPage user={user} onLogin={() => setDialog('login')} />} />
      <Route path="/seller" element={<SellerPage user={user} onLogin={() => setDialog('login')} onNewListing={() => setDialog('sell')} onBecomeSeller={becomeSeller} activating={sellerActivating} activationError={sellerActivationError} />} />
      <Route path="*" element={<main className="min-h-screen bg-white text-ink">
        <header className="topbar"><Brand/><nav className="nav-links"><a href="#discover">Discover</a><a href="#how">How it works</a></nav><div className="top-actions"><ThemeToggle/>{user ? <><span className="welcome">Hi, {user.full_name.split(' ')[0]}</span><Link className="text-button" to="/orders">My orders</Link>{user.role === 'seller' && <Link className="text-button" to="/seller">Seller studio</Link>}{user.role === 'admin' && <Link className="text-button" to="/admin">Admin</Link>}<button className="text-button" onClick={signOut}>Sign out</button></> : <button className="text-button" onClick={() => setDialog('login')}>Log in</button>}<button className="button button-blue button-small" onClick={() => user ? setDialog('sell') : setDialog('register')}>Start selling <span aria-hidden="true" className="arrow-icon"/></button></div></header>
        {notice && <NoticeBar notice={notice} onClose={() => setNotice(null)}/>}
        <section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="pulse"/> MADE FOR CAMPUS LIFE IN ESWATINI</div><h1>Good finds.<br/><span>Good people.</span></h1><p>Buy, sell and find the little things that make student life easier. Right here on campus.</p><div className="hero-actions"><a href="#discover" className="button button-blue">Explore the marketplace <span aria-hidden="true" className="arrow-icon"/></a><button className="button button-light" onClick={() => user ? setDialog('sell') : setDialog('register')}>List something <span>+</span></button></div><div className="social-proof"><div className="avatar-stack"><span>TM</span><span>SN</span><span>BK</span><span>+</span></div><div><strong>Made for students, by students</strong><small>At Limkokwing and campuses across Eswatini</small></div></div></div><div className="hero-art"><div className="art-glow"/><div className="floating-tag tag-top"><span className="tag-dot"/> Student-to-student exchange</div><div className="market-card"><div className="market-card-top"><span>THIS WEEK ON CAMPUS</span><span className="live-dot"> LIVE</span></div><div className="featured-product-media">{featuredListing?.images?.[0] ? <img src={featuredListing.images[0]} alt={featuredListing.title} /> : <div className="featured-product-empty"><span>{featuredListing ? 'PHOTO COMING SOON' : 'NEW ON CAMPUS'}</span></div>}<span className="featured-product-label">{featuredListing?.category_name || 'Campus marketplace'}</span></div><div className="market-card-bottom"><div><small>{featuredListing ? (featuredListing.campus || 'ESWATINI') + ' - JUST LISTED' : 'LATEST CAMPUS PRODUCT'}</small><strong>{featuredListing?.title || 'Find your next campus essential'}</strong></div><b>{featuredListing ? money(featuredListing.price) : 'SZL'}</b></div></div><div className="floating-tag tag-bottom"><span className="mini-shield">OK</span> Browse local listings</div></div></section>
        <section className="trust-strip"><div><strong>Student-first</strong><span>Built around campus communities</span></div><div><strong>Easy to use</strong><span>List it in a few simple steps</span></div><div><strong>Trade with care</strong><span>Clear profiles and safer meetups</span></div><div><strong>Made in Eswatini</strong><span>Local finds, local services</span></div></section>
        <section className="discover-section" id="discover"><div className="section-head"><div><div className="eyebrow">THE CAMPUS MARKETPLACE</div><h2>Find your next <span>favourite.</span></h2></div><a className="browse-link" href="#listings">Browse everything <span aria-hidden="true" className="arrow-icon"/></a></div><div className="market-controls"><div className="tabs"><button className={listingFilter === 'all' ? 'tab active' : 'tab'} onClick={() => setListingFilter('all')}>All</button><button className={listingFilter === 'physical' ? 'tab active' : 'tab'} onClick={() => setListingFilter('physical')}>Physical items</button><button className={listingFilter === 'service' ? 'tab active' : 'tab'} onClick={() => setListingFilter('service')}>Student services</button></div><label className="searchbox"><input aria-label="Search listings" placeholder="Search items, services, campus..." value={search} onChange={(e) => setSearch(e.target.value)} /><button type="button" className="search-clear" onClick={() => setSearch('')} aria-label="Clear search">x</button></label></div><div className="category-row"><button className="category-chip" onClick={() => setSearch('')}>Everything</button>{cats.slice(0,8).map((c) => <button key={c.id} className="category-chip" onClick={() => setSearch(c.name)}>{c.name}</button>)}</div>
          <div className="listing-grid" id="listings">{listingsQuery.isLoading ? <div className="empty-state">Loading listings from Neon...</div> : listingsQuery.isError ? <div className="empty-state"><strong>Marketplace could not load.</strong><br/>Check that the API is online and connected to Neon, then <button className="inline-action" onClick={() => listingsQuery.refetch()}>try again</button>.</div> : listings.length ? listings.map((listing, i) => <article className="listing-card" key={listing.id}><ListingGallery images={listing.images} title={listing.title} category={listing.category_name} type={listing.listing_type} variant={i % 4}/><div className="listing-info"><div className="listing-title-row"><h3>{listing.title}</h3><strong>{money(listing.price)}</strong></div><p>{listing.description}</p><div className="listing-meta"><span><i className="location-dot"/> {listing.campus || 'Eswatini'}</span><span>{listing.seller_name || 'Student seller'}</span></div><button className="listing-request" onClick={() => requestListing(listing)}>{listing.listing_type==='service'?'Request service':'Request item'} <span aria-hidden="true" className="arrow-icon"/></button></div></article>) : <div className="empty-state">No approved {listingFilter === 'physical' ? 'physical items' : listingFilter === 'service' ? 'student services' : 'listings'} found.</div>}</div>
        </section>
        <section className="how-section" id="how"><div className="how-intro"><div className="eyebrow">SIMPLE FROM THE START</div><h2>Campus trading,<br/><span>without the hassle.</span></h2><p>Get what you need, pass on what you don't, and help your campus community thrive.</p><button className="button button-blue" onClick={() => user ? setDialog('sell') : setDialog('register')}>Get started <span aria-hidden="true" className="arrow-icon"/></button></div><div className="steps"><div className="step"><span className="step-number">01</span><div><h3>Find what you need</h3><p>Browse listings and services from students around you.</p></div><span className="step-icon"></span></div><div className="step"><span className="step-number">02</span><div><h3>Place your request</h3><p>Keep track of orders, service requests and updates.</p></div><span className="step-icon arrow-icon"/></div><div className="step"><span className="step-number">03</span><div><h3>Meet and exchange</h3><p>Arrange a safe handoff on campus.</p></div><span className="step-icon"></span></div></div></section>
        <footer className="footer"><Brand/><span>Campus finds, made easy.</span><div><a href="#discover">Marketplace</a><Link to="/orders">My orders</Link><Link to="/seller">Seller studio</Link><Link to="/admin">Admin portal</Link></div><small>Copyright 2026 StudentXchange | Eswatini</small></footer>
      </main>} />
    </Routes>
    {dialog && <div className="modal-backdrop" onMouseDown={(e) => {if(e.target === e.currentTarget) setDialog(null);}}><div className="modal"><button className="modal-close" onClick={() => setDialog(null)} aria-label="Close">x</button><span className="modal-mark">S</span><h2>{dialog === 'login' ? 'Welcome back' : dialog === 'register' ? 'Join your campus' : 'Create a listing'}</h2><p>{dialog === 'sell' ? 'Share something useful with students near you.' : 'A better way to buy, sell and share on campus.'}</p>{dialog === 'sell' ? <form className="modal-form" onSubmit={submitListing}><label>Title<input name="title" required maxLength={180} placeholder="What are you listing?"/></label><label>Listing type<select name="listing_type" value={kind} onChange={(e)=>setKind(e.target.value as 'physical'|'service')}><option value="physical">Physical item</option><option value="service">Student service</option></select></label><label>Price (SZL)<input name="price" type="number" min="1" step="0.01" required/></label>{kind === 'physical' && <label>Available stock<input name="stock" type="number" min="1" defaultValue="1" required/></label>}{kind === 'physical' && <label>Condition<select name="condition"><option value="">Select condition</option><option value="NEW">New</option><option value="LIKE_NEW">Like new</option><option value="GOOD">Good</option><option value="FAIR">Fair</option></select></label>}<label>Details<textarea name="description" required rows={3} maxLength={4000}/></label><label>Upload up to 5 images (JPG, PNG or WebP, max 700 KB each)<input type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={e=>void loadListingImages(e.currentTarget.files)}/></label>{listingImageData.length>0&&<div className="listing-upload-previews" aria-label={`${listingImageData.length} selected listing photos`}>{listingImageData.map((image,index)=><div className="listing-upload-preview-wrap" key={index}><img className="listing-upload-preview" src={image} alt={`Listing photo preview ${index+1}`}/><button type="button" aria-label={`Remove photo ${index+1}`} onClick={()=>setListingImageData(current=>current.filter((_,i)=>i!==index))}>×</button></div>)}</div>}<label>Category<select name="category_id" required disabled={!cats.length}><option value="">Choose a category</option>{cats.map((c)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><button className="button button-blue" disabled={listingMutation.isPending || !cats.length}>Publish listing <span aria-hidden="true" className="arrow-icon"/></button>{listingMutation.isError && <small className="error">{errorText(listingMutation.error,'Sign in with a seller account to list items.')}</small>}</form> : <form className="modal-form" onSubmit={submitAuth}>{dialog === 'register' && <label>Your name<input name="full_name" required maxLength={255}/></label>}<label>Email<input name="email" type="email" required value={authEmail} onChange={e=>setAuthEmail(e.target.value)}/></label>{dialog === 'register' && <><label>Campus<input name="campus" maxLength={255}/></label><label>Phone<input name="phone" type="tel"/></label></>}<label>Password<input name="password" type="password" minLength={8} required/></label>{dialog === 'register' && <label>Account type<select name="role"><option value="customer">Customer</option><option value="seller">Seller and customer</option></select></label>}<button className="button button-blue" disabled={authMutation.isPending}>{dialog === 'login' ? 'Log in' : 'Create account'} <span aria-hidden="true" className="arrow-icon"/></button>{authMutation.isError && <small className="error">{errorText(authMutation.error,'Could not complete sign in. Check your details and try again.')}</small>}{['EMAIL_NOT_VERIFIED','EMAIL_DELIVERY_UNAVAILABLE'].includes((authMutation.error as any)?.response?.data?.code)&&<button type="button" className="switch-auth" disabled={!authEmail||resendVerificationMutation.isPending} onClick={()=>resendVerificationMutation.mutate(authEmail)}>{resendVerificationMutation.isPending?'Sending verification email...':'Resend verification email'}</button>}{resendVerificationMutation.isError&&<small className="error">{errorText(resendVerificationMutation.error,'Could not send the verification email.')}</small>}{resendVerificationMutation.isSuccess&&<small role="status">{resendVerificationMutation.data?.message||'If this is an unverified administrator account, a verification email will be sent.'}</small>}<button type="button" className="switch-auth" onClick={() => setDialog(dialog === 'login' ? 'register' : 'login')}>{dialog === 'login' ? 'New here? Create an account' : 'Already a member? Log in'}</button></form>}</div></div>}
  </>;
}

function NoticeBar({notice,onClose}:{notice:Notice;onClose:()=>void}) { return <div className={`notice notice-${notice.kind}`} role="status">{notice.text}<button onClick={onClose} aria-label="Dismiss">x</button></div>; }

function VerifyEmailPage() {
  const [state,setState]=useState<'checking'|'verified'|'error'>('checking');
  const [message,setMessage]=useState('Confirming your email address...');
  useEffect(()=>{
    const token=new URLSearchParams(window.location.search).get('token');
    if(!token){setState('error');setMessage('This verification link is missing or invalid.');return;}
    api.post('/auth/verify-email',{token}).then(()=>{setState('verified');setMessage('Your email is verified. You can now sign in to StudentXchange.');}).catch((error)=>{setState('error');setMessage(errorText(error,'This verification link is invalid or has expired. Request a new link from the sign-in form.'));});
  },[]);
  return <div className="portal-page"><PortalHeader title="Email verification"/><main className="portal-main"><section className="portal-card portal-empty" aria-live="polite"><span className="eyebrow">STUDENTXCHANGE ACCOUNT</span><h1>{state==='checking'?'Verifying your email':state==='verified'?'Email verified':'Could not verify email'}</h1><p>{message}</p><Link to="/" className="button button-blue">Return to StudentXchange</Link></section></main></div>;
}

function PortalHeader({title,children}:{title:string;children?:ReactNode}) { return <header className="portal-top"><Brand/><strong>{title}</strong><nav>{children}</nav><Link to="/" className="button button-light">Marketplace</Link><ThemeToggle/></header>; }

function KycChecking({onSignOut}:{onSignOut:()=>void}) { return <div className="portal-page"><PortalHeader title="Checking student verification"><button className="text-button" onClick={onSignOut}>Sign out</button></PortalHeader><main className="portal-main"><section className="portal-card portal-empty"><h1>Checking your account</h1><p>Loading your student verification status.</p></section></main></div>; }

function KycGate({user,onSignOut,onRefresh,onSubmitted}:{user:User;onSignOut:()=>void;onRefresh:()=>void;onSubmitted:()=>void}) {
  const [studentId,setStudentId]=useState('');const [photo,setPhoto]=useState('');const [note,setNote]=useState('');const [fileName,setFileName]=useState('');const [uploadError,setUploadError]=useState('');
  const submit=useMutation({mutationFn:async()=>(await api.post('/kyc',{student_id_number:studentId,id_photo_data:photo,note})).data,onSuccess:onSubmitted,onError:error=>setUploadError(errorText(error,'Could not submit your verification.'))});
  function readIdPhoto(file?:File) {
    setUploadError('');if(!file){setPhoto('');setFileName('');return;}
    if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setUploadError('Choose a JPG, PNG or WebP photo.');return;}
    if(file.size>8*1024*1024){setUploadError('The photo must be 8 MB or smaller.');return;}
    const reader=new FileReader();reader.onerror=()=>setUploadError('Could not read this photo.');reader.onload=()=>{const image=new Image();image.onerror=()=>setUploadError('Could not open this photo.');image.onload=()=>{const scale=Math.min(1,1280/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext('2d');if(!context){setUploadError('Image compression is unavailable in this browser.');return;}context.drawImage(image,0,0,canvas.width,canvas.height);for(const quality of [0.9,0.84,0.78,0.72,0.66,0.6]){const data=canvas.toDataURL('image/jpeg',quality);if(data.length<=180000){setPhoto(data);setFileName(file.name);return;}}setUploadError('This photo is too detailed to upload. Try a smaller, clearer photo of the ID card.');};image.src=String(reader.result||'');};reader.readAsDataURL(file);
  }
  const pending=user.kyc_status==='pending';
  return <div className="portal-page kyc-gate"><PortalHeader title="Student verification"><button className="text-button" onClick={onSignOut}>Sign out</button></PortalHeader><main className="portal-main"><section className="portal-card kyc-card"><span className="eyebrow">STUDENT ACCOUNT CHECK</span><h1>{pending?'Verification in review':user.kyc_status==='rejected'?'Update your verification':'Verify your student account'}</h1><p>{pending?'Your student ID has been sent to the admin team. Marketplace access will unlock as soon as it is approved. This page checks for updates automatically.':'Upload a clear photo of your student ID and enter its number. An administrator must approve your verification before you can use the marketplace.'}</p><div className="kyc-status-row"><span className="status-pill">{(user.kyc_status||'not submitted').replaceAll('_',' ')}</span><button className="button button-light" onClick={onRefresh}>Check status</button></div>{!pending&&<form className="modal-form kyc-form" onSubmit={event=>{event.preventDefault();if(!photo){setUploadError('Upload a photo of your student ID.');return;}submit.mutate();}}><label>Student ID number<input value={studentId} onChange={event=>setStudentId(event.target.value)} required minLength={3} maxLength={120} autoComplete="off" placeholder="Enter the number on your ID"/></label><label>Student ID photo (JPG, PNG or WebP, max 8 MB)<input type="file" accept="image/jpeg,image/png,image/webp" onChange={event=>readIdPhoto(event.currentTarget.files?.[0])} required={!photo}/></label>{fileName&&<small className="kyc-file-name">Selected: {fileName}</small>}{photo&&<img className="kyc-photo-preview" src={photo} alt="Student ID photo preview"/>}<label>Note for the admin (optional)<textarea value={note} onChange={event=>setNote(event.target.value)} maxLength={500} rows={3} placeholder="Add any helpful context"/></label>{uploadError&&<small className="error">{uploadError}</small>}<button className="button button-blue" disabled={submit.isPending||!photo}>{submit.isPending?'Submitting...':'Submit student verification'}</button></form>}</section></main></div>;
}

function OrdersPage({user,onLogin}:{user:User|null;onLogin:()=>void}) {
  const [notice,setNotice]=useState<Notice|null>(null); const qc=useQueryClient();
  const orders=useQuery({queryKey:['orders'],queryFn:async()=>(await api.get('/orders')).data,retry:false,enabled:!!user});
  const refresh=()=>qc.invalidateQueries({queryKey:['orders']});
  const mutation=useMutation({mutationFn:async({id,action,body}:{id:string;action:string;body?:any})=>(await api.post(`/orders/${id}/${action}`,body)).data,onSuccess:()=>{refresh();setNotice({kind:'success',text:'Order updated.'})},onError:(e)=>setNotice({kind:'error',text:errorText(e,'Could not update the order.')})});
  useEffect(()=>{const status=new URLSearchParams(window.location.search).get('payment');if(status){setNotice({kind:status==='paid'?'success':status==='review'?'error':'info',text:status==='paid'?'DPO confirmed your payment. It is held while the order is completed.':status==='review'?'DPO confirmed payment, but the order needs administrator review.':'DPO has not confirmed payment yet. Refresh your orders shortly.'});window.history.replaceState({},'',window.location.pathname)}},[]);
  const payment=useMutation({mutationFn:async({id,provider,phone}:{id:string;provider:string;phone?:string})=>(await api.post(`/payments/${provider}/start`,{order_id:id,phone})).data,onSuccess:(data)=>{if(data.checkout?.url){window.location.assign(data.checkout.url);return}refresh();setNotice({kind:'info',text:data.checkout?.message||data.error||data.next||'Payment request started.'})},onError:(e)=>setNotice({kind:'error',text:errorText(e,'Could not start payment.')})});
  const checkMomo=useMutation({mutationFn:async(id:string)=>(await api.get(`/payments/momo/status/${id}`)).data,onSuccess:(data)=>{refresh();setNotice({kind:data.status==='successful'?'success':data.status==='needs_review'||data.status==='failed'?'error':'info',text:data.status==='successful'?'MTN confirmed payment. Funds are held until delivery is completed.':data.status==='needs_review'?'Payment completed and needs admin review.':data.status==='failed'?'MTN declined the request. You can retry or choose another payment method.':`MTN payment status: ${data.status||'pending'}. Approve the request on your phone if it is still pending.`})},onError:(e)=>setNotice({kind:'error',text:errorText(e,'Could not check the MTN MoMo payment.')})});
  if(!user)return <div className="portal-page"><PortalHeader title="My orders"/><section className="portal-card portal-empty"><h1>Your orders live here</h1><p>Sign in to see your purchase and seller activity.</p><button onClick={onLogin} className="button button-blue">Sign in</button></section></div>;
  return <div className="portal-page"><PortalHeader title="My orders"><Link to="/seller">Seller studio</Link></PortalHeader>{notice&&<NoticeBar notice={notice} onClose={()=>setNotice(null)}/>}<main className="portal-main"><div className="portal-heading"><div><span className="eyebrow">CUSTOMER + SELLER</span><h1>Orders</h1><p>Track requests, payment status and escrow decisions.</p></div><button className="button button-light" onClick={()=>orders.refetch()}>Refresh</button></div>{orders.isLoading?<div className="portal-card">Loading your orders...</div>:orders.isError?<RetryCard onRetry={()=>orders.refetch()} message={errorText(orders.error,'Could not load orders.')}/>:orders.data?.length?<div className="portal-list">{orders.data.map((order:any)=><article className="portal-card order-card" key={order.id}><div className="order-title"><div><span className="eyebrow">ORDER {order.id.slice(0,8)}</span><h2>{order.item_titles||'Campus order'}</h2><p>{new Date(order.created_at).toLocaleString()}  |  Seller: {order.seller_name}  |  Buyer: {order.buyer_name}</p></div><strong>{money(order.total_amount,order.currency)}</strong></div><div className="order-status"><span className={`status-pill status-${order.status}`}>{order.status.replaceAll('_',' ')}</span><span>Escrow: {order.escrow_status||'awaiting payment'}{order.held_amount?`  |  ${money(order.held_amount,order.currency)} held`:''}</span></div><div className="portal-actions">{order.status==='pending_payment'&&<><button className="button button-light" disabled={payment.isPending} onClick={()=>payment.mutate({id:order.id,provider:'dpo'})}>Card  |  DPO Pay</button><button className="button button-light" disabled={payment.isPending} onClick={()=>{const phone=window.prompt('MTN MoMo phone number (Eswatini)');if(phone)payment.mutate({id:order.id,provider:'momo',phone})}}>Mobile money  |  MTN</button>{order.payment_method==='MTN_MOMO'&&order.momo_reference_id&&<button className="button button-light" disabled={checkMomo.isPending} onClick={()=>checkMomo.mutate(order.id)}>{checkMomo.isPending?'Checking MTN...':'Check MTN payment'}</button>}<button className="button button-danger" disabled={mutation.isPending} onClick={()=>{if(window.confirm('Cancel this unpaid request and return the item to stock?'))mutation.mutate({id:order.id,action:'cancel'})}}>Cancel unpaid order</button></>}{order.escrow_status==='held'&&order.seller_id===user.id&&!order.delivered_at&&<button className="button button-light" onClick={()=>mutation.mutate({id:order.id,action:'delivered'})}>Mark delivered</button>}{order.escrow_status==='held'&&order.buyer_id===user.id&&<button className="button button-blue" onClick={()=>mutation.mutate({id:order.id,action:'confirm'})}>Confirm receipt</button>}{['held','withheld_by_admin'].includes(order.escrow_status)&&<button className="button button-light" onClick={()=>{const reason=window.prompt('What is the issue?');if(!reason)return;const details=window.prompt('Describe what happened.');if(details)mutation.mutate({id:order.id,action:'dispute',body:{reason,details}})}}>Open a dispute</button>}</div></article>)}</div>:<section className="portal-card portal-empty"><h2>No orders yet</h2><p>Find something you like in the marketplace and place a request.</p><Link to="/" className="button button-blue">Browse marketplace</Link></section>}</main></div>;
}

function SellerPage({user,onLogin,onNewListing,onBecomeSeller,activating,activationError}:{user:User|null;onLogin:()=>void;onNewListing:()=>void;onBecomeSeller:()=>void;activating:boolean;activationError:string}) {
  const [notice,setNotice]=useState<Notice|null>(null);const qc=useQueryClient();
  const data=useQuery({queryKey:['seller','listings'],queryFn:async()=>(await api.get('/seller/listings')).data,retry:false,enabled:user?.role==='seller'});
  const listing=useMutation({mutationFn:async({id,status}:{id:string;status:string})=>(status==='removed'?api.delete(`/listings/${id}`):api.patch(`/listings/${id}`,{status})),onSuccess:()=>{data.refetch();qc.invalidateQueries({queryKey:['listings']});qc.invalidateQueries({queryKey:['featured-listing']});setNotice({kind:'success',text:'Listing updated.'})},onError:e=>setNotice({kind:'error',text:errorText(e,'Could not update listing.')})});
  if(!user)return <div className="portal-page"><PortalHeader title="Seller studio"/><section className="portal-card portal-empty"><h1>Seller studio</h1><p>Sign in with a seller account to manage listings and verification.</p><button onClick={onLogin} className="button button-blue">Sign in</button></section></div>;
  if(user.role!=='seller')return <div className="portal-page"><PortalHeader title="Seller studio"/><main className="portal-main"><section className="portal-card portal-empty"><h1>Open your seller studio</h1><p>Your customer account can also sell. Activate seller access to publish and manage listings.</p>{activationError&&<small className="error" role="alert">{activationError}</small>}<button type="button" className="button button-blue" onClick={()=>{void onBecomeSeller();}} disabled={activating} aria-busy={activating}>{activating?'Activating seller access...':'Become a seller'}</button></section></main></div>;
  return <div className="portal-page"><PortalHeader title="Seller studio"><Link to="/orders">My orders</Link></PortalHeader>{notice&&<NoticeBar notice={notice} onClose={()=>setNotice(null)}/>}<main className="portal-main"><div className="portal-heading"><div><span className="eyebrow">YOUR CAMPUS BUSINESS</span><h1>Seller studio</h1><p>Listings are checked by an administrator before appearing in the marketplace.</p></div><button className="button button-blue" onClick={onNewListing}>+ New listing</button></div>{data.isError&&<RetryCard onRetry={()=>data.refetch()} message={errorText(data.error,'Could not load seller data.')}/>}<section className="portal-card"><div className="section-title"><div><h2>Student verification</h2><p>Your student account was approved by an administrator.</p></div><span className="status-pill">{user.kyc_status||'approved'}</span></div></section><div className="portal-heading compact"><div><h2>Your listings</h2><p>{data.data?.listings?.length||0} submissions</p></div><button className="button button-light" onClick={()=>data.refetch()}>Refresh</button></div>{data.isLoading?<div className="portal-card">Loading seller studio...</div>:data.data?.listings?.length?<div className="portal-list">{data.data.listings.map((row:any)=><article className="portal-card order-card" key={row.id}><div className="order-title"><div><span className="eyebrow">{row.category_name}  |  {row.listing_type}</span><h2>{row.title}</h2><p>{row.description}</p></div><strong>{money(row.price)}</strong></div><div className="order-status"><span className="status-pill">{row.status==='pending_review'?'Awaiting admin review':row.status}</span><span>Stock: {row.stock}</span></div><div className="portal-actions">{row.status==='active'&&<button className="button button-light" onClick={()=>listing.mutate({id:row.id,status:'paused'})}>Pause listing</button>}{row.status==='paused'&&<span className="listing-review-note">An administrator must approve this listing before it can be relisted.</span>}{row.status!=='removed'&&<button className="button button-danger" onClick={()=>{if(window.confirm(`Remove "${row.title}" from the marketplace?`))listing.mutate({id:row.id,status:'removed'})}}>Remove</button>}</div></article>)}</div>:!data.isError?<section className="portal-card portal-empty"><h2>No listings yet</h2><button className="button button-blue" onClick={onNewListing}>Create your first listing</button></section>:null}</main></div>;
}

function RetryCard({message,onRetry}:{message:string;onRetry:()=>void}) { return <section className="portal-card error-card"><p>{message}</p><button className="button button-light" onClick={onRetry}>Try again</button></section>; }

type AdminTab='escrow'|'kyc'|'categories'|'disputes'|'payouts'|'users'|'listings';
const printEscape=(value:unknown)=>String(value??'Not provided').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]!));
function AdminPage({user,onLogin,onSignOut}:{user:User|null;onLogin:()=>void;onSignOut:()=>void}) {
  const [tab,setTab]=useState<AdminTab>('escrow');const [notice,setNotice]=useState<Notice|null>(null);const [printingUserId,setPrintingUserId]=useState<string|null>(null);const qc=useQueryClient();
  const endpoints:Record<AdminTab,string>={escrow:'/admin/escrow',kyc:'/admin/kyc',categories:'/admin/categories',disputes:'/admin/disputes',payouts:'/admin/payouts',users:'/admin/users',listings:'/admin/listings'};
  const data=useQuery({queryKey:['admin',tab],queryFn:async()=>(await api.get(endpoints[tab])).data,retry:false,enabled:user?.role==='admin'});
  const refresh=()=>{qc.invalidateQueries({queryKey:['admin']});qc.invalidateQueries({queryKey:['categories']});qc.invalidateQueries({queryKey:['listings']});qc.invalidateQueries({queryKey:['featured-listing']});qc.invalidateQueries({queryKey:['seller']});};
  const action=useMutation({mutationFn:async({method,path,body}:{method:'post'|'patch'|'delete';path:string;body?:any})=>api[method](path,body),onSuccess:()=>{refresh();setNotice({kind:'success',text:'Admin change saved.'})},onError:e=>setNotice({kind:'error',text:errorText(e,'Could not save this admin change.')})});
  async function printUserRecord(id:string){
    const printWindow=window.open('','_blank');
    if(!printWindow){setNotice({kind:'error',text:'Allow pop-ups for this site to print a user record.'});return;}
    printWindow.opener=null;setPrintingUserId(id);
    try {
      const {data:record}=await api.get(`/admin/users/${encodeURIComponent(id)}/print-record`);
      const logoResponse=await fetch('/studentxchange-logo.png');
      if(!logoResponse.ok)throw new Error('Could not load the StudentXchange logo.');
      const logoBlob=await logoResponse.blob();
      const logoDataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==='string'?resolve(reader.result):reject(new Error('Could not prepare the logo for printing.'));reader.onerror=()=>reject(new Error('Could not prepare the logo for printing.'));reader.readAsDataURL(logoBlob);});
      const photo=typeof record.id_photo_url==='string'&&(/^(https?:\/\/|data:image\/)/i).test(record.id_photo_url)?`<img class="id-photo" src="${printEscape(record.id_photo_url)}" alt="Student verification document">`:'';
      const date=(value:unknown)=>value?new Date(String(value)).toLocaleString():'Not provided';
      printWindow.document.open();
      printWindow.document.write(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StudentXchange user record</title><style>
        *{box-sizing:border-box}body{font:14px/1.5 Arial,sans-serif;color:#172033;margin:0;padding:36px}.sheet{max-width:760px;margin:auto}.brand{display:flex;align-items:center;gap:12px;font-size:13px;letter-spacing:.12em;font-weight:700;color:#075985}.brand img{width:54px;height:54px;object-fit:contain;border-radius:50%}h1{font-size:28px;margin:8px 0 4px}.muted{color:#526174}.section{margin-top:26px;border-top:2px solid #dbe4ed;padding-top:14px}h2{font-size:16px;margin:0 0 12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px 24px}.field small{display:block;color:#66768a;font-size:11px;text-transform:uppercase;letter-spacing:.06em}.field strong{overflow-wrap:anywhere}.id-photo{display:block;max-width:100%;max-height:340px;object-fit:contain;margin-top:14px;border:1px solid #cbd5e1}.footer{margin-top:32px;padding-top:10px;border-top:1px solid #dbe4ed;font-size:11px;color:#66768a}@media print{body{padding:0}.sheet{max-width:none}.no-print{display:none!important}}@media(max-width:540px){body{padding:20px}.grid{grid-template-columns:1fr}}
        </style></head><body><main class="sheet"><div class="brand"><img src="${printEscape(logoDataUrl)}" alt="StudentXchange logo"><span>STUDENTXCHANGE · ADMIN RECORD</span></div><h1>${printEscape(record.full_name)}</h1><div class="muted">Generated ${printEscape(new Date().toLocaleString())}</div>
        <section class="section"><h2>Account details</h2><div class="grid"><div class="field"><small>Email</small><strong>${printEscape(record.email)}</strong></div><div class="field"><small>Phone</small><strong>${printEscape(record.phone)}</strong></div><div class="field"><small>Campus</small><strong>${printEscape(record.campus)}</strong></div><div class="field"><small>Account roles</small><strong>${printEscape((record.roles||[]).join(', ')||'Not provided')}</strong></div><div class="field"><small>Account status</small><strong>${printEscape(record.status)}</strong></div><div class="field"><small>Account created</small><strong>${printEscape(date(record.created_at))}</strong></div></div></section>
        <section class="section"><h2>Student verification</h2><div class="grid"><div class="field"><small>Verification status</small><strong>${printEscape(record.kyc_status)}</strong></div><div class="field"><small>Student ID number</small><strong>${printEscape(record.student_id_number)}</strong></div><div class="field"><small>Submission status</small><strong>${printEscape(record.verification_status)}</strong></div><div class="field"><small>Submitted</small><strong>${printEscape(date(record.verification_submitted_at))}</strong></div><div class="field"><small>Last updated</small><strong>${printEscape(date(record.verification_updated_at))}</strong></div><div class="field"><small>Note</small><strong>${printEscape(record.verification_note)}</strong></div></div>${photo}</section>
        <div class="footer">Confidential account information. Printed by an authorized StudentXchange administrator.</div><button class="no-print" onclick="window.print()">Print this record</button></main></body></html>`);
      printWindow.document.close();
      const logoImage=printWindow.document.querySelector('.brand img') as HTMLImageElement|null;
      try{await logoImage?.decode();}catch{/* Keep the printable record available if this browser cannot decode the logo. */}
      printWindow.focus();printWindow.print();
    } catch(error){printWindow.close();setNotice({kind:'error',text:errorText(error,'Could not create the user record.')});}
    finally{setPrintingUserId(null);}
  }
  if(user?.role!=='admin')return <div className="admin-gate"><Brand/><section><span className="eyebrow">ADMIN PORTAL</span><h1>Platform oversight,<br/><span>in one place.</span></h1><p>Sign in with an administrator account to review escrow, student verification, disputes and payouts.</p><button className="button button-blue" onClick={onLogin}>Sign in as admin <span aria-hidden="true" className="arrow-icon"/></button><Link to="/" className="browse-link">Back to marketplace</Link></section></div>;
  const tabs:AdminTab[]=['escrow','kyc','categories','disputes','payouts','users','listings'];
  function doAction(method:'post'|'patch'|'delete',path:string,body?:any){action.mutate({method,path,body});}
  return <div className="portal-page"><PortalHeader title="Admin portal"><Link to="/orders">My orders</Link><button className="text-button" onClick={onSignOut}>Sign out</button></PortalHeader>{notice&&<NoticeBar notice={notice} onClose={()=>setNotice(null)}/>}<main className="portal-main"><div className="portal-heading"><div><span className="eyebrow">PLATFORM OPERATIONS</span><h1>Admin workspace</h1><p>Review students, approve listings, and manage transactions.</p></div><button className="button button-light" onClick={()=>data.refetch()}>Refresh</button></div><div className="admin-tabs" role="tablist">{tabs.map(item=><button key={item} className={tab===item?'admin-tab active':'admin-tab'} onClick={()=>setTab(item)} role="tab" aria-selected={tab===item}>{item==='kyc'?'Student verification':item==='users'?'Users':item==='listings'?'Listings':item[0].toUpperCase()+item.slice(1)}</button>)}</div>{data.isLoading?<section className="portal-card">Loading {tab}...</section>:data.isError?<RetryCard onRetry={()=>data.refetch()} message={errorText(data.error,'Could not load this queue.')}/>:<div className="portal-list">
    {tab==='users'&&(data.data||[]).map((row:any)=><article className="portal-card admin-item" key={row.id}><div><span className="eyebrow">{(row.roles||[]).join(' / ')}  |  {row.kyc_status} verification</span><h2>{row.full_name}</h2><p>{row.email}  |  {row.campus||'Campus not provided'}  |  {row.listing_count} listings</p><span className={`status-pill status-${row.status}`}>{row.status}</span></div><div className="portal-actions"><button className="button button-light" disabled={printingUserId===row.id} onClick={()=>void printUserRecord(row.id)}>{printingUserId===row.id?'Preparing...':'Print record'}</button>{row.id!==user?.id&&<>{row.status==='active'?<button className="button button-light" onClick={()=>doAction('patch',`/admin/users/${row.id}`,{status:'suspended'})}>Pause account</button>:<button className="button button-light" onClick={()=>doAction('patch',`/admin/users/${row.id}`,{status:'active'})}>Restore account</button>}{row.status!=='banned'&&<button className="button button-danger" onClick={()=>{if(window.confirm(`Ban ${row.full_name} from StudentXchange?`))doAction('patch',`/admin/users/${row.id}`,{status:'banned'})}}>Ban</button>}{!row.roles?.includes('admin')&&<button className="button button-danger" onClick={()=>{if(window.confirm(`Delete ${row.full_name}'s account? Personal details and verification photos will be removed; order records will be retained.`))doAction('delete',`/admin/users/${row.id}`)}}>Delete account</button>}</>}</div></article>)}
    {tab==='listings'&&(data.data||[]).map((row:any)=><article className="portal-card admin-item admin-listing" key={row.id}><div className="admin-listing-main">{row.images?.[0]&&<img className="admin-listing-image" src={row.images[0]} alt={row.title}/>}<div><span className="eyebrow">{row.category_name}  |  {row.listing_type}</span><h2>{row.title}  |  {money(row.price)}</h2><p>{row.description}</p><p>Seller: {row.seller_name} ({row.seller_email})  |  {row.campus||'Campus not provided'}  |  KYC: {row.kyc_status}</p><span className={`status-pill status-${row.status}`}>{row.status.replaceAll('_',' ')}</span></div></div><div className="portal-actions">{row.status!=='active'&&row.status!=='removed'&&<button className="button button-blue" onClick={()=>doAction('patch',`/admin/listings/${row.id}`,{status:'active'})}>{row.status==='pending_review'?'Approve listing':'Approve / relist'}</button>}{row.status==='active'&&<button className="button button-light" onClick={()=>doAction('patch',`/admin/listings/${row.id}`,{status:'paused'})}>Pause listing</button>}{row.status!=='removed'&&<button className="button button-danger" onClick={()=>{if(window.confirm(`Remove "${row.title}" from the marketplace and clear its photo?`))doAction('delete',`/admin/listings/${row.id}`)}}>Remove listing</button>}</div></article>)}
    {tab==='escrow'&&(data.data||[]).map((row:any)=><article className="portal-card admin-item" key={row.order_id}><div><span className="eyebrow">ORDER {row.order_id.slice(0,8)}</span><h2>{money(row.held_amount)}  |  {row.status}</h2><p>{row.withheld_reason||'Funds held while order is completed.'}</p></div><div className="portal-actions">{row.status==='held'&&<button className="button button-light" onClick={()=>{const reason=window.prompt('Reason for withholding the funds?');if(reason)doAction('post',`/admin/escrow/${row.order_id}/hold`,{reason})}}>Withhold</button>}<button className="button button-blue" disabled={row.status==='disputed'} onClick={()=>{if(window.confirm('Release this held amount to the seller payout queue?'))doAction('post',`/admin/escrow/${row.order_id}/release`)}}>Release</button></div></article>)}
    {tab==='kyc'&&(data.data||[]).map((row:any)=><article className="portal-card admin-item" key={row.id}><div><span className="eyebrow">STUDENT ID  |  {row.student_id_number}</span><h2>{row.full_name}</h2><p>{row.email}  |  {row.campus||'Campus not provided'}  |  {row.note||'No note'}{row.id_photo_url&&<a href={row.id_photo_url} target="_blank" rel="noreferrer"><img className="kyc-admin-photo" src={row.id_photo_url} alt="Student ID submitted for verification"/></a>}</p></div><div className="portal-actions"><button className="button button-light" onClick={()=>doAction('patch',`/admin/kyc/${row.id}`,{status:'rejected'})}>Reject</button><button className="button button-blue" onClick={()=>doAction('patch',`/admin/kyc/${row.id}`,{status:'approved'})}>Approve</button></div></article>)}
    {tab==='categories'&&<><CategoryCreator onCreate={(body)=>doAction('post','/admin/categories',body)}/>{(data.data||[]).map((row:any)=><article className="portal-card admin-item" key={row.id}><div><span className="eyebrow">{row.category_type}</span><h2>{row.name}</h2><p>/{row.slug}  |  {row.is_active?'Active':'Inactive'}</p></div><div className="portal-actions"><button className="button button-light" onClick={()=>doAction('patch',`/admin/categories/${row.id}`,{is_active:!row.is_active})}>{row.is_active?'Deactivate':'Reactivate'}</button><button className="button button-danger" onClick={()=>{if(window.confirm(`Deactivate category "${row.name}"?`))doAction('delete',`/admin/categories/${row.id}`)}}>Remove</button></div></article>)}</>}
    {tab==='disputes'&&(data.data||[]).map((row:any)=><article className="portal-card admin-item" key={row.id}><div><span className="eyebrow">OPEN DISPUTE  |  ORDER {row.order_id.slice(0,8)}</span><h2>{row.reason}  |  {money(row.order_total)}</h2><p>{row.details}  |  Raised by {row.raised_by}</p></div><div className="portal-actions"><button className="button button-light" onClick={()=>{const note=window.prompt('Resolution note (required)');if(note)doAction('post',`/admin/disputes/${row.id}/resolve`,{outcome:'buyer',note})}}>Refund buyer</button><button className="button button-blue" onClick={()=>{const note=window.prompt('Resolution note (required)');if(note)doAction('post',`/admin/disputes/${row.id}/resolve`,{outcome:'seller',note})}}>Release to seller</button><button className="button button-light" onClick={()=>{const sellerAmount=window.prompt(`Seller gross share in SZL (order total ${row.order_total})`);if(sellerAmount===null)return;const buyerAmount=window.prompt('Buyer refund in SZL');if(buyerAmount===null)return;const note=window.prompt('Resolution note (required)');if(note)doAction('post',`/admin/disputes/${row.id}/resolve`,{outcome:'split',seller_amount:sellerAmount,buyer_amount:buyerAmount,note})}}>Split funds</button></div></article>)}
    {tab==='payouts'&&(data.data||[]).map((row:any)=><article className="portal-card admin-item" key={row.id}><div><span className="eyebrow">PAYOUT  |  ORDER {row.order_id.slice(0,8)}</span><h2>{row.seller_name}  |  {money(row.amount)}</h2><p>Status: {row.status}{row.provider_reference?`  |  Reference ${row.provider_reference}`:''}</p></div>{row.status==='pending'&&<div className="portal-actions"><button className="button button-light" onClick={()=>doAction('patch',`/admin/payouts/${row.id}`,{status:'failed'})}>Mark failed</button><button className="button button-blue" onClick={()=>{const reference=window.prompt('Payout reference (optional)');doAction('patch',`/admin/payouts/${row.id}`,{status:'paid',provider_reference:reference||''})}}>Mark paid</button></div>}</article>)}
    {!data.data?.length&&tab!=='categories'&&<section className="portal-card portal-empty"><h2>Nothing needs review</h2><p>This queue is up to date.</p></section>}
  </div>}</main></div>;
}

function CategoryCreator({onCreate}:{onCreate:(body:any)=>void}){const[name,setName]=useState('');const[type,setType]=useState<'physical'|'service'>('physical');return <form className="portal-card portal-form category-create" onSubmit={e=>{e.preventDefault();const slug=name.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(slug){onCreate({name:name.trim(),slug,category_type:type});setName('')}}}><label>New category<input required value={name} onChange={e=>setName(e.target.value)} maxLength={140}/></label><label>Tree<select value={type} onChange={e=>setType(e.target.value as 'physical'|'service')}><option value="physical">Physical items</option><option value="service">Services</option></select></label><button className="button button-blue">Add category</button></form>}

export default App;
